lumn":"id"},{"constraint_name":"workplace_queue_positions_task_id_fkey","from_object":"workplace_queue_positions","from_column":"task_id","to_object":"tasks","to_column":"id"}]}$catalog$::jsonb);

with objects as (
  select value as item
  from ai_catalog_import_payload, jsonb_array_elements(payload->'objects')
)
update public.ai_entities e
set entity_kind = o.item->>'object_kind',
    updated_at = now(),
    metadata = e.metadata || jsonb_build_object(
      'catalog_source','information_schema',
      'catalog_imported_at',now()
    )
from objects o
where e.source_schema='public'
  and e.source_object=o.item->>'object_name';

with objects as (
  select value as item
  from ai_catalog_import_payload, jsonb_array_elements(payload->'objects')
)
insert into public.ai_entities
  (code,business_name,entity_kind,source_schema,source_object,description,sensitivity,metadata)
select 'source_' || (o.item->>'object_name'),
       o.item->>'object_name',
       o.item->>'object_kind',
       'public',
       o.item->>'object_name',
       'Автоматически импортированное описание объекта основной базы.',
       case when o.item->>'object_name' like 'employee%' then 'personal' else 'internal' end,
       jsonb_build_object('catalog_source','information_schema','catalog_imported_at',now())
from objects o
where not exists (
  select 1 from public.ai_entities e
  where e.source_schema='public'
    and e.source_object=o.item->>'object_name'
);

update public.ai_entities e
set description = a.reason,
    sensitivity = case
      when cardinality(a.sensitive_columns) > 0 then 'personal'
      when cardinality(a.financial_columns) > 0 then 'financial'
      else e.sensitivity
    end,
    metadata = e.metadata || jsonb_build_object(
      'requires_golden_query',a.requires_golden_query,
      'sensitive_columns',a.sensitive_columns,
      'financial_columns',a.financial_columns
    ),
    updated_at = now()
from public.ai_allowed_objects a
where a.schema_name='public'
  and a.object_kind in ('table','view')
  and e.source_schema=a.schema_name
  and e.source_object=a.object_name;

with fields as (
  select o->>'object_name' as object_name, c as column_item
  from ai_catalog_import_payload,
       jsonb_array_elements(payload->'objects') o,
       jsonb_array_elements(o->'columns') c
)
insert into public.ai_fields
  (entity_id,column_name,business_name,data_type,description,sensitivity,pitfalls,source_reference,metadata)
select e.id,
       f.column_item->>'name',
       f.column_item->>'name',
       f.column_item->>'data_type',
       'Поле импортировано из метаданных основной базы.',
       case
         when f.column_item->>'name' ~* '(password|hash|token|secret|iin)' then 'secret'
         when f.column_item->>'name' ~* '(salary|pay_rate|price|cost|amount|coefficient)' then 'financial'
         when f.column_item->>'name' ~* '(employee|user|first_name|last_name|patronymic|phone|address|login)' then 'personal'
         else 'internal'
       end,
       case when f.column_item->>'name' ~* '(password|hash|token|secret)'
            then array['Запрещено выбирать и возвращать.']::text[]
            else '{}'::text[] end,
       'public.' || f.object_name,
       jsonb_build_object(
         'nullable',(f.column_item->>'nullable')::boolean,
         'ordinal',(f.column_item->>'ordinal')::integer,
         'catalog_source','information_schema'
       )
from fields f
join public.ai_entities e
  on e.source_schema='public' and e.source_object=f.object_name
on conflict (entity_id,column_name) do update set
  data_type=excluded.data_type,
  metadata=public.ai_fields.metadata || excluded.metadata,
  updated_at=now();

with fks as (
  select value as item
  from ai_catalog_import_payload, jsonb_array_elements(payload->'foreign_keys')
)
insert into public.ai_relationships
  (code,from_entity_id,to_entity_id,relationship_kind,cardinality,join_expression,description,confirmed_by_human,metadata)
select 'FK-' || (f.item->>'constraint_name') || '-' || (f.item->>'from_column'),
       fe.id,
       te.id,
       'foreign_key',
       'many_to_one',
       (f.item->>'from_object') || '.' || (f.item->>'from_column') || ' = ' ||
         (f.item->>'to_object') || '.' || (f.item->>'to_column'),
       'Внешний ключ, импортированный из основной базы.',
       true,
       jsonb_build_object(
         'constraint_name',f.item->>'constraint_name',
         'catalog_source','information_schema'
       )
from fks f
join public.ai_entities fe
  on fe.source_schema='public' and fe.source_object=f.item->>'from_object'
join public.ai_entities te
  on te.source_schema='public' and te.source_object=f.item->>'to_object'
on conflict (code) do update set
  from_entity_id=excluded.from_entity_id,
  to_entity_id=excluded.to_entity_id,
  join_expression=excluded.join_expression,
  metadata=excluded.metadata,
  updated_at=now();

commit;
